public class CategoryPlot_getRangeAxisIndex_TriageGen2Test {

    private CategoryPlot categoryPlot;
    private ValueAxis mockAxis;

    @Before
    public void setUp() {
        categoryPlot = new CategoryPlot();
        mockAxis = mock(ValueAxis.class);
    }

    /**
     * Tests that when the axis is found directly in the rangeAxes list, 
     * the correct index is returned.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInLocalAxes() throws Exception {
        // Use reflection to access the private rangeAxes list if necessary, 
        // but CategoryPlot provides setRangeAxes.
        ValueAxis axis1 = mock(ValueAxis.class);
        ValueAxis axis2 = mock(ValueAxis.class);
        categoryPlot.setRangeAxes(new ValueAxis[]{axis1, axis2});

        assertEquals(0, categoryPlot.getRangeAxisIndex(axis1));
        assertEquals(1, categoryPlot.getRangeAxisIndex(axis2));
    }

    /**
     * Tests that when the axis is NOT found in the local rangeAxes, 
     * it attempts to delegate to the parent plot if the parent is a CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundLocally_FoundInParentCategoryPlot() throws Exception {
        // Create a parent CategoryPlot
        CategoryPlot parentPlot = new CategoryPlot();
        ValueAxis parentAxis = mock(ValueAxis.class);
        parentPlot.setRangeAxis(parentAxis);

        // Set the parent of our current plot using reflection since getParent() is likely protected/internal
        setPrivateField(categoryPlot, "parent", parentPlot);

        // The axis is not in categoryPlot, but is in parentPlot
        assertEquals(0, categoryPlot.getRangeAxisIndex(parentAxis));
    }

    /**
     * Tests that when the axis is NOT found locally and the parent is NOT a CategoryPlot, 
     * it returns -1.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundLocally_ParentIsNotCategoryPlot() throws Exception {
        // Mock a different type of Plot (e.g., XYPlot or just a generic Plot)
        Plot genericParent = mock(Plot.class);
        setPrivateField(categoryPlot, "parent", genericParent);

        // Axis is not in categoryPlot
        assertEquals(-1, categoryPlot.getRangeAxisIndex(mockAxis));
    }

    /**
     * Tests that when the axis is NOT found locally and there is no parent, 
     * it returns -1.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundLocally_NoParent() {
        // By default parent is null
        assertEquals(-1, categoryPlot.getRangeAxisIndex(mockAxis));
    }

    /**
     * Helper method to set private fields for testing purposes (parent plot).
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
